import { useGesture } from '@use-gesture/react';
import { Bounds } from '@visx/brush/lib/types';
import { PickD3Scale, TimeDomain } from '@visx/scale';
import clsx from 'clsx';
import React, { useMemo, useState } from 'react';

import { TimeseriesCrosshair } from './TimeseriesCrosshair.js';
import { TimeseriesInspect } from './TimeseriesInspect.js';
import {
  divPlotLayout,
  svgPlotLayout,
} from '../../../../core/components/chart-grid/ChartGridRoot.sty.js';
import { useGridPlotSize } from '../../../../core/components/chart-grid/hooks/useGridPlotSize.js';
import { OVERLAY_PADDING } from '../../../../core/components/data-point/constants.js';
import { usePanning } from '../../../../core/components/zoom/hooks/usePanning.js';
import { ZoomBrush } from '../../../../core/components/zoom/ZoomBrush.js';
import { cursorStyle } from '../../../../core/components/zoom/ZoomCursors.sty.js';
import { getGroupedDataPointsByCoordinate } from '../../../../core/functions/group-by-threshold.js';
import {
  useCurrentDomainState,
  useSetState,
} from '../../../hooks/store/selectors.js';
import { useChartInteractions } from '../../../hooks/useChartInteractions.js';
import { useTimeseriesFilteredData } from '../../../hooks/useTimeseriesFilteredData.js';
import { useTimeseriesXFormatter } from '../../../hooks/useTimeseriesXFormatter.js';
import { useXScales } from '../../../hooks/useXScale.js';
import { useYScales } from '../../../hooks/useYScales.js';
import { middleMouseClick } from '../constants.js';
import { usePinnedAwarePosition } from '../hooks/usePinnedAwarePosition.js';
import { brushOverlay } from '../TimeseriesOverlays.sty.js';
import { EMPTY_DATAPOINT } from '../utils/tooltip/constants.js';
import {
  filterOutOfBounds,
  findClosestPoints,
  getClosestPoint,
} from '../utils/tooltip/find-closest-points.js';
import { filterTimestampsAndTimeframes } from '../utils/tooltip/timeseries-tooltip.js';

type XZoomState = 'idle' | 'down' | 'dragging';

type PanState = 'idle' | 'panning';

export const TimeseriesExploreOverlay = () => {
  const { width, height } = useGridPlotSize();
  const { currentScale: xScale, initialScale } = useXScales();
  const { datapointsMap, allDatapoints } = useTimeseriesFilteredData();
  const setState = useSetState();
  const yScale = useYScales();
  const mousePosition = usePinnedAwarePosition();
  const { left, right } = useYScales();
  const [xZoomState, setXZoomState] = useState<XZoomState>('idle');
  const { onZoomChange, zoomX, pan } = useChartInteractions();
  const currentDomain = useCurrentDomainState();
  const isChartWithZoom = Boolean(currentDomain);
  const isPanEnabled = pan?.enabled && isChartWithZoom;
  const plotRef = React.useRef<HTMLDivElement>(null);
  const [panState, setPanState] = useState<PanState>('idle');
  const xFormatter = useTimeseriesXFormatter();

  const handleBrushEnd = (domain: Bounds) => {
    onZoomChange &&
      onZoomChange(new Date(domain.x0), new Date(domain.x1), 'zoom-x');
    setState((prev) => ({
      ...prev,
      currentDomain: [domain.x0, domain.x1],
      zoom: {
        ...prev.zoom,
        zoomOutEnabled: true,
      },
    }));
    setXZoomState('down');
  };

  const getBrushLabelFromPoint = (xTime: number): string => {
    return xFormatter(new Date(xTime));
  };

  function handlePan(domain: TimeDomain) {
    setState((prev) => ({
      ...prev,
      currentDomain: domain,
    }));
  }

  function handlePanEnd([min, max]: Date[]) {
    setPanState('idle');
    onZoomChange?.(min, max, 'panning');
  }

  const { onDrag, onDragEnd } = usePanning({
    initialXScale: initialScale as PickD3Scale<'time'>,
    xScale: xScale as PickD3Scale<'time'>,
    onPanning: handlePan,
    onPanningEnd: handlePanEnd,
  });

  const isNotPanning = panState !== 'panning';

  useGesture(
    {
      onDrag: (event) => {
        setPanState('panning');
        onDrag && onDrag(event);
      },
      onDragEnd,
    },
    {
      target: plotRef,
      eventOptions: { passive: false },
      drag: { pointer: { buttons: middleMouseClick } },
      enabled: isPanEnabled,
    },
  );

  const isNotDragging = xZoomState !== 'dragging';

  const { closestPoint, filteredPoints, groupedPoints } = useMemo(() => {
    const xPoints =
      mousePosition && isNotDragging
        ? findClosestPoints(
            mousePosition.x,
            mousePosition.y,
            allDatapoints,
            xScale,
            yScale,
            datapointsMap,
          )
            .map((point) => {
              point.x = point.x + OVERLAY_PADDING;
              point.y = point.y + OVERLAY_PADDING;

              return point;
            })
            .filter(filterOutOfBounds(width))
        : [];
    const closestPoint =
      xPoints.length > 0
        ? getClosestPoint(xPoints, mousePosition?.y)
        : EMPTY_DATAPOINT;

    const filteredPoints = filterTimestampsAndTimeframes(xPoints, closestPoint);
    const groupedPoints = getGroupedDataPointsByCoordinate(xPoints, 'y');

    return { closestPoint, filteredPoints, groupedPoints };
    //FYI: This mouse position is aware of the pinned state, which helps avoid unnecessary calculations.
  }, [mousePosition?.x, mousePosition?.y]);

  const handleTogglePinTooltip = () => {
    const highlightedSeriesId = closestPoint?.id
      ? [closestPoint?.id]
      : undefined;

    setState((prev) => ({
      ...prev,
      highlightedSeriesIds: prev.overlays.pinnedTooltip
        ? undefined
        : highlightedSeriesId,
      overlays: {
        ...prev.overlays,
        pinnedTooltip: !prev.overlays.pinnedTooltip,
      },
    }));
  };

  const handleClick = () => {
    if (xZoomState === 'idle') {
      handleTogglePinTooltip();
    }

    setXZoomState('idle');
  };

  return (
    <div
      ref={plotRef}
      onClick={handleClick}
      className={clsx(cursorStyle({ isPanEnabled }), divPlotLayout)}
    >
      {isNotDragging && isNotPanning && (
        <TimeseriesInspect
          filteredPoints={filteredPoints}
          closestPoint={closestPoint}
          groupedPoints={groupedPoints}
        />
      )}
      {isNotDragging && isNotPanning && (
        <TimeseriesCrosshair closestPoint={closestPoint} />
      )}
      {zoomX?.enabled && (
        <svg className={clsx(svgPlotLayout, brushOverlay)}>
          {isNotPanning && (
            <ZoomBrush
              width={width}
              height={height}
              xScale={xScale as PickD3Scale<'linear', number>}
              yScale={left?.scale ?? right!.scale}
              onBrushChange={() => setXZoomState('dragging')}
              onBrushEnd={handleBrushEnd}
              labelAccessor={getBrushLabelFromPoint}
            />
          )}
        </svg>
      )}
    </div>
  );
};
